#include <memory>
#include <print>

int main() {
    for (int i = 0; i < 1000000; ++i) {
        auto one = std::make_unique<int>(i);   // 每圈出大括号就还，一句 delete 都不用写
    }
    // 这一百万圈跑完，一格都没漏：无泄漏、无悬垂，全靠作用域

    auto arr = std::make_unique<int[]>(10);
    for (int i = 0; i < 10; ++i) arr[i] = i + 1;

    int sum = 0;
    for (int i = 0; i < 10; ++i) sum += arr[i];
    std::println("和 = {}", sum);
    // 要一串东西就交给 vector 自己管内存，单个对象要活得比花括号久才轮到智能指针，这就是那 99%
    return 0;
}

